{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "cycle-phased-strength-intro",
    "name": "Cycle-Phased Strength — 2-Week Intro Block",
    "description": "A 2-week introductory strength block phased around a 28-day menstrual cycle. Week 1 falls in the late-follicular window (cycle days ~31-37 relative to last period start 2026-05-01, i.e. programme days 1-7 map to cycle days 31-37 ≈ cycle days 3-9 of the new cycle). Flow days 1-3 of any cycle are protected: no high-intensity work, no heavy Valsalva, no jumping. Outside that window the client is fully cleared for progressive strength training.",
    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-01T00:00:00Z",
      "updated_at": "2026-06-01T00:00:00Z",
      "created_by": "trainer",
      "tags": ["cycle-phased", "strength", "dysmenorrhea", "beginner-intermediate", "female-health"],
      "difficulty": "beginner",
      "estimated_duration_days": 14,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-strength-foundation",
        "type": "primary",
        "category": "strength",
        "name": "Build a safe strength foundation",
        "description": "Establish movement quality and baseline strength across the main compound patterns before progressing load in later phases."
      },
      {
        "id": "goal-cycle-literacy",
        "type": "secondary",
        "category": "wellbeing",
        "name": "Train in harmony with the menstrual cycle",
        "description": "Protect flow days 1-3 from high-intensity and high-intra-abdominal-pressure work; leverage the follicular energy window for progressive overload."
      }
    ],
    "requirements": {
      "min_age": 18,
      "max_age": 45,
      "fitness_level": ["recreational", "intermediate"],
      "equipment": [
        { "id": "barbell", "name": "Barbell", "required": false, "alternatives": ["dumbbells"] },
        { "id": "dumbbells", "name": "Dumbbells", "required": true },
        { "id": "resistance-bands", "name": "Resistance Bands", "required": false },
        { "id": "bench", "name": "Flat Bench", "required": true },
        { "id": "pull-up-bar", "name": "Pull-up Bar / Cable Machine", "required": false, "alternatives": ["resistance-bands"] }
      ],
      "contraindications": [
        {
          "condition": "icd10:N94.4",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "flow-day-heavy-squat", "flow-day-deadlift", "flow-day-jumping", "flow-day-hiit"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 4,
        "min_minutes_per_day": 30,
        "max_minutes_per_day": 60
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "cycle_day",
          "type": "number",
          "source": "wellness.menstrual_phase",
          "label": "Current cycle day (1 = first day of period)"
        },
        {
          "id": "session_rpe_yesterday",
          "type": "number",
          "source": "wellness.session_rpe_yesterday",
          "label": "Yesterday's session RPE (1-10)"
        },
        {
          "id": "subjective_readiness",
          "type": "number",
          "source": "wellness.subjective_readiness",
          "label": "Subjective readiness today (1-10)"
        }
      ],
      "rules": [
        {
          "id": "rule-flow-day-swap",
          "condition": {
            "field": "cycle_day",
            "op": "lte",
            "value": 3
          },
          "actions": [
            {
              "type": "swap_block",
              "scope": "main",
              "replacement": "gentle-flow-day-block",
              "reason": "Cycle days 1-3: replace strength main block with low-intensity mobility and breathwork per GP contraindication."
            }
          ]
        },
        {
          "id": "rule-low-readiness-deload",
          "condition": {
            "field": "subjective_readiness",
            "op": "lte",
            "value": 4
          },
          "actions": [
            {
              "type": "scale_load",
              "scope": "main",
              "factor": 0.8,
              "reason": "Low readiness: reduce prescribed load by 20% and cap RPE at 6."
            }
          ]
        }
      ]
    },
    "athlete_thresholds": {
      "body_weight_kg": 65,
      "resting_hr_bpm": 62,
      "hr_max_bpm": 192
    },
    "phases": [
      {
        "id": "phase-intro",
        "name": "Introductory Reconditioning Block",
        "order": 1,
        "type": "accumulation",
        "description": "Two weeks of technique-first, moderate-load training. Week 1 (programme start 2026-06-01) falls on approximately cycle day 31 of the previous cycle, i.e. cycle day 3 of the new cycle — so Monday is a protected flow-day session. From Tuesday onward the client is in the follicular phase and cleared for progressive work. Week 2 is fully in the follicular/pre-ovulatory window: energy and strength are typically at their monthly peak.",
        "duration": { "value": 2, "unit": "weeks" },
        "weeks": [
          {
            "id": "week-1",
            "name": "Week 1 — Late Flow / Early Follicular",
            "order": 1,
            "is_deload": false,
            "days": [
              {
                "id": "w1d1",
                "day_of_week": 1,
                "type": "active_recovery",
                "name": "Monday — Flow Day 3 (Protected)",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "w1d1-b1",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "w1d1-diaphragmatic-breathing",
                        "type": "recovery",
                        "name": "Diaphragmatic Breathing",
                        "category": "breathwork",
                        "prescription": {
                          "duration": { "value": 5, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "w1d1-breath-ex",
                              "type": "recovery_exercise",
                              "name": "360° Diaphragmatic Breath",
                              "modality": "breathwork",
                              "hold_seconds": 4,
                              "reps": 10,
                              "body_part": "abs"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d1-b2",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "w1d1-supine-hip-flexor",
                        "type": "recovery",
                        "name": "Gentle Mobility & Stretch Circuit",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 20, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "w1d1-hip-flexor-stretch",
                              "type": "recovery_exercise",
                              "name": "Supine Knee-to-Chest",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 4,
                              "body_part": "hip_flexors"
                            },
                            {
                              "id": "w1d1-childs-pose",
                              "type": "recovery_exercise",
                              "name": "Child's Pose",
                              "modality": "static_stretch",
                              "hold_seconds": 45,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 3,
                              "body_part": "lower_back"
                            },
                            {
                              "id": "w1d1-cat-cow",
                              "type": "recovery_exercise",
                              "name": "Cat-Cow Spinal Mobilisation",
                              "modality": "mobility_drill",
                              "reps": 10,
                              "sides": "both",
                              "intensity_rpe": 2,
                              "body_part": "spinal_erectors"
                            },
                            {
                              "id": "w1d1-glute-stretch",
                              "type": "recovery_exercise",
                              "name": "Supine Figure-4 Glute Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "intensity_rpe": 4,
                              "body_part": "glutes"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d1-b3",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "w1d1-meditation",
                        "type": "meditation",
                        "name": "Body-Scan Relaxation",
                        "category": "relaxation",
                        "prescription": {
                          "duration": { "value": 5, "unit": "minutes" },
                          "guided": true
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1d2",
                "day_of_week": 2,
                "type": "rest",
                "name": "Tuesday — Rest",
                "estimated_duration_minutes": 0
              },
              {
                "id": "w1d3",
                "day_of_week": 3,
                "type": "training",
                "name": "Wednesday — Lower Body Strength (Follicular)",
                "estimated_duration_minutes": 55,
                "blocks": [
                  {
                    "id": "w1d3-b1",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "w1d3-warmup-cardio",
                        "type": "cardio",
                        "name": "Light Bike / Treadmill Walk",
                        "modality": "cycling",
                        "prescription": {
                          "type": "continuous",
