                        "secondary_muscles": ["glutes", "abs"],
                        "movement_pattern": "squat",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 12, "unit": "kg" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 1, "pause_top": 0 }
                        }
                      },
                      {
                        "id": "w1d3-rdl",
                        "type": "exercise",
                        "exercise_ref": "romanian-deadlift-db",
                        "name": "Dumbbell Romanian Deadlift",
                        "primary_muscles": ["hamstrings"],
                        "secondary_muscles": ["glutes", "spinal_erectors"],
                        "movement_pattern": "hinge",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 10, "unit": "kg" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 1, "pause_top": 0 }
                        }
                      },
                      {
                        "id": "w1d3-split-squat",
                        "type": "exercise",
                        "exercise_ref": "db-split-squat",
                        "name": "Dumbbell Split Squat",
                        "primary_muscles": ["quadriceps"],
                        "secondary_muscles": ["glutes", "hip_flexors"],
                        "movement_pattern": "lunge",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d3-b3",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "w1d3-cooldown",
                        "type": "recovery",
                        "name": "Lower Body Cooldown Stretch",
                        "category": "flexibility",
                        "prescription": {
                          "duration": { "value": 8, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "w1d3-quad-stretch",
                              "type": "recovery_exercise",
                              "name": "Standing Quad Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 1,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "quadriceps"
                            },
                            {
                              "id": "w1d3-hamstring-stretch",
                              "type": "recovery_exercise",
                              "name": "Seated Hamstring Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 1,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "hamstrings"
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1d4",
                "day_of_week": 4,
                "type": "rest",
                "name": "Thursday — Rest",
                "estimated_duration_minutes": 0
              },
              {
                "id": "w1d5",
                "day_of_week": 5,
                "type": "training",
                "name": "Friday — Upper Body Strength (Follicular)",
                "estimated_duration_minutes": 55,
                "blocks": [
                  {
                    "id": "w1d5-b1",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "w1d5-band-pull-apart",
                        "type": "exercise",
                        "exercise_ref": "band-pull-apart",
                        "name": "Band Pull-Apart",
                        "primary_muscles": ["rear_delts"],
                        "secondary_muscles": ["traps"],
                        "movement_pattern": "pull_horizontal",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "target": 15 },
                          "rest": { "value": 30, "unit": "seconds" },
                          "weight": { "type": "bodyweight" }
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d5-b2",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "w1d5-db-bench",
