                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 12, "unit": "kg" }
                        }
                      },
                      {
                        "id": "w1d5-db-ohp",
                        "type": "exercise",
                        "exercise_ref": "db-overhead-press",
                        "name": "Seated Dumbbell Overhead Press",
                        "primary_muscles": ["front_delts"],
                        "secondary_muscles": ["side_delts", "triceps"],
                        "movement_pattern": "push_vertical",
                        "target_rpe": 6,
                        "target_rir": 3,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d5-b3",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "w1d5-cooldown",
                        "type": "recovery",
                        "name": "Upper Body Cooldown Stretch",
                        "category": "flexibility",
                        "prescription": {
                          "duration": { "value": 8, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "w1d5-chest-stretch",
                              "type": "recovery_exercise",
                              "name": "Doorway Chest Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 1,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "chest"
                            },
                            {
                              "id": "w1d5-lat-stretch",
                              "type": "recovery_exercise",
                              "name": "Overhead Lat Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 1,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "lats"
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1d6",
                "day_of_week": 6,
                "type": "active_recovery",
                "name": "Saturday — Active Recovery Walk",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "w1d6-b1",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "w1d6-walk",
                        "type": "cardio",
                        "name": "Easy Outdoor Walk",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
