                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1d7",
                "day_of_week": 7,
                "type": "rest",
                "name": "Sunday — Full Rest",
                "estimated_duration_minutes": 0
              }
            ]
          },
          {
            "id": "week-2",
            "name": "Week 2 — Follicular / Pre-Ovulatory (Peak Energy Window)",
            "order": 2,
            "is_deload": false,
            "days": [
              {
                "id": "w2d1",
                "day_of_week": 1,
                "type": "training",
